import { createStore } from '@/lib/store'
import { apiEnabled, del, get, patch, post } from '@/lib/api'
import { createLoader, fetchAll, toastError } from './bizApi'
import {
  SEED_EMPLOYEES,
  createEmptyEmployee,
  type Employee,
  type EmployeeStatus,
  type JobType,
} from './employees'

// API mode (VITE_API_URL): employee onboarding records come from /onboarding/employees (id = onboardingId; employee / TP
// codes are generated by the backend). Mutations update the store first, then go to the backend in order per record.
export const employeeStore = createStore<Employee[]>(
  apiEnabled ? 'dexter.employees.api.v1' : 'dexter.employees.v1',
  () => (apiEnabled ? [] : SEED_EMPLOYEES),
)

export const useEmployees = () => {
  employeeLoader.use()
  return employeeStore.use()
}
/** Loading state of the API hydration (always loaded in mock mode). */
export const useEmployeesLoad = () => employeeLoader.use()

export function getEmployee(idOrCode: string): Employee | undefined {
  const all = employeeStore.get()
  const key = serverId.get(idOrCode) ?? idOrCode
  return all.find(
    (e) =>
      e.id === key ||
      e.employeeCode.toLowerCase() === key.toLowerCase() ||
      e.tpCode.toLowerCase() === key.toLowerCase(),
  )
}

export function nextEmployeeCode(): string {
  if (apiEnabled) return `${TEMP}${Date.now().toString(36).toUpperCase()}`
  const all = employeeStore.get()
  const highestNum = all.reduce((max, e) => {
    const match = e.employeeCode.match(/(\d+)$/)
    if (match) {
      const num = parseInt(match[1], 10)
      return Math.max(max, num)
    }
    return max
  }, 252615)
  return `DITMP${highestNum + 1}`
}

export function nextTpCode(): string {
  if (apiEnabled) return 'Assigned on save'
  const all = employeeStore.get()
  const highestNum = all.reduce((max, e) => {
    const match = e.tpCode.match(/(\d+)$/)
    if (match) {
      const num = parseInt(match[1], 10)
      return Math.max(max, num)
    }
    return max
  }, 33694)
  return `TP${highestNum + 1}`
}

export function saveEmployee(employee: Employee): Employee {
  const now = new Date().toISOString()
  const existing = employee.id ? getEmployee(employee.id) : apiEnabled && employee.employeeCode ? getEmployee(employee.employeeCode) : undefined

  const toSave: Employee = {
    ...employee,
    id: existing?.id || employee.id || (apiEnabled ? employee.employeeCode || `${TEMP}${Date.now().toString(36).toUpperCase()}` : `EMP-2025-${String(Date.now()).slice(-4)}`),
    employeeCode: employee.employeeCode || existing?.employeeCode || nextEmployeeCode(),
    tpCode: employee.tpCode || existing?.tpCode || nextTpCode(),
    // API mode: status only changes through the approval action (setEmployeeStatus)
    status: apiEnabled && existing ? existing.status : apiEnabled ? 'Pending' : employee.status,
    updatedAt: now,
    createdAt: existing?.createdAt || now,
  }

  employeeStore.set((list) => {
    const exists = list.some((e) => e.id === toSave.id)
    if (exists) {
      return list.map((e) => (e.id === toSave.id ? toSave : e))
    }
    return [toSave, ...list]
  })

  if (apiEnabled) remoteSave(toSave)
  return toSave
}

/**
 * Delete. API mode: soft delete — DELETE /onboarding/employees/:id {reason}, allowed while not activated (status
 * Pending, no employee id; else `NOT_DRAFT` → shown, list re-hydrated). Mock mode: removes locally.
 */
export function deleteEmployee(id: string, reason?: string): boolean {
  if (apiEnabled) {
    const sid = sidOf(rootOf(id))
    if (sid && (reason?.trim().length ?? 0) < 3) {
      toastError(new Error('A reason (at least 3 characters) is required.'), 'Delete employee')
      return false
    }
    employeeStore.set((list) => list.filter((e) => e.id !== id))
    if (sid)
      del(`/onboarding/employees/${encodeURIComponent(sid)}`, { reason: reason!.trim() }).catch((e: unknown) => {
        toastError(e, 'Delete employee')
        void employeeLoader.reload()
      })
    return true
  }
  employeeStore.set((list) => list.filter((e) => e.id !== id))
  return true
}

export function setEmployeeStatus(ids: string[], status: EmployeeStatus, reason?: string) {
  const now = new Date().toISOString()
  employeeStore.set((list) =>
    list.map((e) => (ids.includes(e.id) ? { ...e, status, updatedAt: now } : e)),
  )
  if (apiEnabled)
    ids.forEach((id) =>
      enqueue(id, async (sid) => {
        if (!sid) throw new Error('The record is still being saved — try again in a moment.')
        replace(id, fromApi(await post<ApiEmployee>(`/onboarding/employees/${encodeURIComponent(sid)}/status`, { status, reason })))
      }),
    )
}

export { createEmptyEmployee }

// ══════════════════════════════ Backend API ══════════════════════════════
const TEMP = 'NEW-'
const serverId = new Map<string, string>() // temporary id / code → onboardingId

type ApiEmployee = {
  onboardingId: string
  employeeCode: string
  tpCode: string
  onboardAs?: JobType
  fullName: string
  mobile?: string
  email?: string
  dateOfJoining?: string
  status: EmployeeStatus
  department?: string
  designation?: string
  reportingManager?: string
  project?: string
  profile?: Partial<Employee>
  createdAt?: string
  updatedAt?: string
}

/** Top-level backend fields; every other Employee field travels in `profile`. */
const TOP = ['id', 'onboardAs', 'employeeCode', 'tpCode', 'fullName', 'mobile', 'email', 'dateOfJoining', 'status', 'department', 'designation', 'reportingManager', 'project', 'createdAt', 'updatedAt'] as const

function fromApi(x: ApiEmployee): Employee {
  return {
    ...createEmptyEmployee(),
    ...(x.profile ?? {}),
    id: x.onboardingId,
    onboardAs: x.onboardAs ?? 'Permanent',
    employeeCode: x.employeeCode,
    tpCode: x.tpCode,
    fullName: x.fullName,
    mobile: x.mobile ?? '',
    email: x.email ?? '',
    dateOfJoining: String(x.dateOfJoining ?? '').slice(0, 10),
    status: x.status,
    department: x.department ?? '',
    designation: x.designation ?? '',
    reportingManager: x.reportingManager ?? '',
    project: x.project ?? '',
    createdAt: String(x.createdAt ?? ''),
    updatedAt: String(x.updatedAt ?? ''),
  }
}

function toApi(e: Employee) {
  const profile: Record<string, unknown> = {}
  for (const [k, v] of Object.entries(e)) if (!(TOP as readonly string[]).includes(k) && v !== '' && v !== undefined) profile[k] = v
  // the photo is a data URL — too large for the profile document; never echo a masked account number back
  delete profile.photoUrl
  if (typeof profile.accountNumber === 'string' && /X/i.test(profile.accountNumber)) delete profile.accountNumber
  const opt = (v: string) => (v?.trim() ? v.trim() : undefined)
  return {
    onboardAs: e.onboardAs,
    fullName: e.fullName.trim(),
    mobile: /^[6-9]\d{9}$/.test(e.mobile) ? e.mobile : undefined,
    email: opt(e.email),
    dateOfJoining: opt(e.dateOfJoining),
    department: opt(e.department),
    designation: opt(e.designation),
    reportingManager: opt(e.reportingManager),
    project: opt(e.project),
    profile,
  }
}

function replace(localId: string, emp: Employee) {
  if (localId !== emp.id) serverId.set(localId, emp.id)
  employeeStore.set((list) => {
    const at = list.findIndex((e) => e.id === localId || e.id === emp.id)
    const rest = list.filter((e) => e.id !== localId && e.id !== emp.id)
    return at < 0 ? [emp, ...rest] : [...rest.slice(0, at), emp, ...rest.slice(at)]
  })
}

const queues = new Map<string, Promise<void>>()
const rootOf = (id: string) => [...serverId.entries()].find(([, v]) => v === id)?.[0] ?? id
const sidOf = (root: string) => serverId.get(root) ?? (root.startsWith(TEMP) ? null : root)
function enqueue(localId: string, fn: (sid: string | null) => Promise<void>) {
  const root = rootOf(localId)
  const next = (queues.get(root) ?? Promise.resolve())
    .then(() => fn(sidOf(root)))
    .catch((e) => {
      toastError(e, 'Employee onboarding')
      const sid = sidOf(root)
      if (sid) refreshEmployee(sid).catch(() => undefined)
      else employeeStore.set((list) => list.filter((x) => x.id !== root))
    })
  queues.set(root, next)
}

function remoteSave(e: Employee) {
  enqueue(e.id, async (sid) => {
    const body = toApi(e)
    const out = sid ? await patch<ApiEmployee>(`/onboarding/employees/${encodeURIComponent(sid)}`, body) : await post<ApiEmployee>('/onboarding/employees', body)
    replace(sid ?? e.id, { ...fromApi(out), photoUrl: e.photoUrl })
    if (!sid) {
      serverId.set(e.id, out.onboardingId)
      serverId.set(e.employeeCode, out.onboardingId)
    }
  })
}

export async function refreshEmployee(id: string) {
  if (!apiEnabled) return
  const x = await get<ApiEmployee>(`/onboarding/employees/${encodeURIComponent(serverId.get(id) ?? id)}`)
  replace(x.onboardingId, { ...fromApi(x), photoUrl: getEmployee(x.onboardingId)?.photoUrl ?? '' })
}

export const employeeLoader = createLoader('employee onboarding', async () => {
  const items = await fetchAll<ApiEmployee>('/onboarding/employees')
  const photos = new Map(employeeStore.get().map((e) => [e.id, e.photoUrl]))
  const pending = employeeStore.get().filter((e) => e.id.startsWith(TEMP) && !serverId.has(e.id))
  employeeStore.set([...pending, ...items.map((x) => ({ ...fromApi(x), photoUrl: photos.get(x.onboardingId) ?? '' }))])
})
